from shipping import fee


def test_fee_for_in_range_amounts():
    for amount in (5000, 0, 9999):
        result = fee(amount)
        assert isinstance(result, int) and not isinstance(result, bool)
        assert result == 1000

from shipping import fee


def test_fee_at_and_above_free_shipping_threshold():
    for amount in (10000, 10001):
        result = fee(amount)
        assert isinstance(result, int) and not isinstance(result, bool)
        assert result == 0

